using System.Net.Http.Headers;using System.Net.Http.Json;using System.Security.Cryptography;using System.Text.Json;
namespace AssetFlow.Agent;
public sealed class AgentClient{public const string Version="0.2.1";private readonly HttpClient http;private readonly AgentState state;public AgentClient(HttpClient http,AgentState state){this.http=http;this.state=state;http.Timeout=TimeSpan.FromMinutes(5);}public async Task EnsureRegistered(CancellationToken ct){if(!string.IsNullOrEmpty(state.Options.DeviceToken))return;var key=Convert.ToHexString(SHA256.HashData(System.Text.Encoding.UTF8.GetBytes($"{Environment.MachineName}|{GetMachineGuid()}")));using var req=new HttpRequestMessage(HttpMethod.Post,$"{state.Options.ApiUrl.TrimEnd('/')}/api/v1/agents/register");req.Headers.Add("X-Registration-Token",state.Options.RegistrationToken);req.Content=JsonContent.Create(new{agentKey=key,hostname=Environment.MachineName,version=Version});using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();var value=await res.Content.ReadFromJsonAsync<Registered>(cancellationToken:ct)??throw new InvalidOperationException("Empty registration response");state.Save(state.Options with{DeviceToken=value.DeviceToken,AgentId=value.AgentId});}public async Task SendInventory(Inventory data,CancellationToken ct)=>await Send("inventory",data,ct);public async Task Heartbeat(CancellationToken ct)=>await Send("heartbeat",new{version=Version},ct);public async Task<AgentRelease?> LatestRelease(CancellationToken ct){using var req=Authorized(HttpMethod.Get,"updates/latest");using var res=await http.SendAsync(req,ct);if(res.StatusCode==System.Net.HttpStatusCode.NoContent)return null;res.EnsureSuccessStatusCode();return await res.Content.ReadFromJsonAsync<AgentRelease>(cancellationToken:ct);}public async Task DownloadRelease(string version,string target,CancellationToken ct){using var req=Authorized(HttpMethod.Get,$"updates/{Uri.EscapeDataString(version)}/download");using var res=await http.SendAsync(req,HttpCompletionOption.ResponseHeadersRead,ct);res.EnsureSuccessStatusCode();await using var input=await res.Content.ReadAsStreamAsync(ct);await using var output=new FileStream(target,FileMode.Create,FileAccess.Write,FileShare.None);await input.CopyToAsync(output,ct);}private HttpRequestMessage Authorized(HttpMethod method,string path){var req=new HttpRequestMessage(method,$"{state.Options.ApiUrl.TrimEnd('/')}/api/v1/agents/{path}");req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",state.Options.DeviceToken);return req;}private async Task Send(string path,object value,CancellationToken ct){using var req=Authorized(HttpMethod.Post,path);req.Content=JsonContent.Create(value);using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();}private static string GetMachineGuid(){using var k=Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Cryptography");return k?.GetValue("MachineGuid")?.ToString()??Environment.MachineName;}private sealed record Registered(string AgentId,string DeviceToken);}
public sealed record AgentRelease(string Version,string Sha256,long Size,string DownloadUrl);
